const slug = ($json.project_slug ?? $json['Project Slug'] ?? '').toString().trim().toLowerCase().replace(/[^a-z0-9-]/g, '');
if (!slug) throw new Error('Project Slug is required.');
const extra = ($json.extra_direction ?? $json['Extra Direction (optional)'] ?? '').toString().trim();
return [{ json: { slug, payloadB64: Buffer.from(JSON.stringify({ slug, extra_direction: extra })).toString('base64') } }];

const res = JSON.parse(($json.stdout ?? '').toString().trim());
if (!res.ok) throw new Error(res.error || 'Failed to load project story.');
const story = (res.story ?? '').toString().trim();
const extra = (res.extra_direction ?? '').toString().trim();
const title = (res.title ?? 'Untitled').toString();
const VOICES = ['alloy', 'ash', 'coral', 'echo', 'fable', 'onyx', 'nova', 'sage', 'shimmer'];

let prompt = [
'You are a film script writer and storyboard artist. Convert the story below into a shot-by-shot script.',
'',
'RULES:',
'- Return ONLY strict JSON. No markdown fences, no commentary.',
'- 4 to 12 shots total, grouped into 1 to 4 scenes.',
'- Each character: id (snake_case), name, visual_description (detailed, stable wording for image generation), reference_images (empty array), voice (one of: ' + VOICES.join(', ') + '), tts_model ("gpt-4o-mini-tts" or "tts-1"), tts_instructions (short delivery direction).',
'- Each shot: id ("shot_001" style, sequential across scenes), image_prompt (self-contained English description of ONE 16:9 frame; refer to characters by name), characters (array of character ids present, may be empty for scenery), narration (string or null) OR dialogue (array of {character, text}), duration_hint_sec (3 to 12), motion ("auto").',
'- A shot has EITHER narration or dialogue, never both. Lines must be under 240 characters each.',
'- Top level also: title, style_notes (visual style for image generation), narrator_voice (from the voice list), narrator_instructions.',
'',
'SCHEMA:',
'{"title":string,"slug":string,"style_notes":string,"narrator_voice":string,"narrator_instructions":string,"characters":[{"id":string,"name":string,"visual_description":string,"reference_images":[],"voice":string,"tts_model":string,"tts_instructions":string}],"scenes":[{"id":string,"title":string,"shots":[{"id":string,"image_prompt":string,"characters":[string],"narration":string|null,"dialogue":[{"character":string,"text":string}],"duration_hint_sec":number,"motion":"auto"}]}]}',
'',
'Set the top-level "slug" exactly to: ' + res.slug,
'STORY TITLE: ' + title,
'STORY:',
story,
].join('\n');
if (extra) prompt += '\n\nEXTRA DIRECTION FROM THE AUTHOR (follow it):\n' + extra;

return [{ json: { slug: res.slug, title, prompt } }];

const slug = ($json.slug ?? '').toString();
const raw = ($json.output ?? '').toString().trim();
const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
let s;
try { s = JSON.parse(cleaned); } catch (e) {
  throw new Error('Script output was not valid JSON: ' + raw.slice(0, 300));
}
const VOICES = new Set(['alloy', 'ash', 'coral', 'echo', 'fable', 'onyx', 'nova', 'sage', 'shimmer']);
const charsIn = Array.isArray(s.characters) ? s.characters : [];
const charMap = {};
charsIn.forEach((c, i) => {
  const id = (c.id ?? 'char_' + (i + 1)).toString().toLowerCase().replace(/[^a-z0-9_]/g, '_') || ('char_' + (i + 1));
  charMap[id] = {
    id,
    name: (c.name ?? id).toString(),
    visual_description: (c.visual_description ?? '').toString(),
    reference_images: [],
    voice: VOICES.has(c.voice) ? c.voice : 'coral',
    tts_model: c.tts_model === 'tts-1' ? 'tts-1' : 'gpt-4o-mini-tts',
    tts_instructions: (c.tts_instructions ?? '').toString().slice(0, 500),
  };
});
const scenes = [];
let n = 0;
for (const sc of (Array.isArray(s.scenes) ? s.scenes : [])) {
  const shots = [];
  for (const sh of (Array.isArray(sc.shots) ? sc.shots : [])) {
    const imagePrompt = (sh.image_prompt ?? '').toString().trim();
    if (!imagePrompt) continue;
    const narration = sh.narration ? sh.narration.toString().trim() : null;
    let dialogue = Array.isArray(sh.dialogue)
      ? sh.dialogue.map((d) => ({
          character: (d.character ?? '').toString().toLowerCase().replace(/[^a-z0-9_]/g, '_'),
          text: (d.text ?? '').toString().trim(),
        })).filter((d) => d.text)
      : [];
    n += 1;
    const dur = Number(sh.duration_hint_sec);
    shots.push({
      id: 'shot_' + String(n).padStart(3, '0'),
      image_prompt: imagePrompt,
      characters: Array.isArray(sh.characters) ? sh.characters.map((x) => x.toString().toLowerCase().replace(/[^a-z0-9_]/g, '_')) : [],
      narration: narration || null,
      dialogue,
      duration_hint_sec: Math.min(15, Math.max(2, Number.isFinite(dur) && dur > 0 ? dur : 5)),
      motion: ['zoom_in', 'zoom_out', 'pan_left', 'pan_right'].includes(sh.motion) ? sh.motion : 'auto',
    });
  }
  if (shots.length) scenes.push({ id: 'scene_' + (scenes.length + 1), title: (sc.title ?? '').toString(), shots });
}
if (!scenes.length) throw new Error('Parsed script contains no usable shots.');
const script = {
  title: (s.title ?? 'Untitled').toString(),
  slug,
  language: 'en',
  aspect: '16:9',
  fps: 25,
  resolution: '1920x1080',
  style_notes: (s.style_notes ?? '').toString(),
  narrator_voice: VOICES.has(s.narrator_voice) ? s.narrator_voice : 'fable',
  narrator_instructions: (s.narrator_instructions ?? '').toString(),
  characters: Object.values(charMap),
  scenes,
};
return [{ json: {
  slug,
  shotCount: n,
  scriptB64: Buffer.from(JSON.stringify(script, null, 2)).toString('base64'),
}}];
